import type { BreadcrumbsProps } from "./breadcrumbs.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Breadcrumbs";

// Generate child element class names for the component, should match available style slots
export const BreadcrumbsClasses = {
  root: "exp-textura_breadcrumbs",
  list: "exp-textura_breadcrumbs_list",
  listItem: "exp-textura_breadcrumbs_list_item",
  overflowItem: "exp-textura_breadcrumbs_overflow_item",
  item: "exp-textura_breadcrumbs_item",
  dropdownIconButton: "exp-textura_breadcrumbs_dropdown_icon_button",
  divider: "exp-textura_breadcrumbs_divider",
  ellipsis: "exp-textura_breadcrumbs_ellipsis",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: BreadcrumbsProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<BreadcrumbsProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "flex",
    alignItems: "center",
    gap: theme.toRem(theme.spacing[8]),
    minWidth: 0,
    width: props.autoOverflow ? "100%" : undefined,

    // Item styles
    [`& .${BreadcrumbsClasses.item}`]: {
      display: "inline-flex",
      justifyContent: "space-between",
      whiteSpace: "nowrap",
      "&[data-current='true']": {
        ...theme.typography.label.sm,
        ...styleSlots?.itemCurrent,
      },
      "&[data-disabled='true'],&[disabled]": {
        pointerEvents: "none",
      },
      ...styleSlots?.item,
    },

    [`& .${BreadcrumbsClasses.dropdownIconButton}`]: {
      display: "flex",
      justifyContent: "center",
      ...styleSlots?.dropdownIconButton,
    },

    [`& ol > li + li:has(.${BreadcrumbsClasses.dropdownIconButton}):not(.${BreadcrumbsClasses.overflowItem})`]:
      {
        marginInlineStart: `calc(${theme.toRem(theme.spacing[4])} - ${theme.toRem(theme.spacing[12])})`,
      },

    [`& .${BreadcrumbsClasses.overflowItem}`]: {
      gap: theme.toRem(theme.spacing[4]),
    },

    [`& .${BreadcrumbsClasses.ellipsis}`]: {
      color: theme.color.content.weak,
      ...styleSlots?.ellipsis,
    },

    [`& .${BreadcrumbsClasses.divider}`]: {
      display: "flex",
      color: theme.color.content.weak,
      ...theme.typography.label.md,
      "&[data-disabled='true']": {
        color: theme.color.content.disabled,
        ...styleSlots?.dividerDisabled,
      },
      ...styleSlots?.divider,
    },

    [`& ol.${BreadcrumbsClasses.list}`]: {
      listStyle: "none",
      padding: 0,
      margin: 0,
      display: "flex",
      alignItems: "center",
      gap: theme.toRem(theme.spacing[12]),
      minWidth: 0,
      width: props.autoOverflow ? "100%" : undefined,
      flexGrow: props.autoOverflow ? 1 : undefined,
      flexShrink: props.autoOverflow ? 1 : undefined,
      ...styleSlots?.list,
    },
    [`& .${BreadcrumbsClasses.listItem}`]: {
      display: "flex",
      alignItems: "center",
      "&[data-breadcrumb-hidden='true']": {
        visibility: "hidden",
        position: "absolute",
        zIndex: -1,
      },
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = [...getExcludedDOMProps(), "autoOverflow"];

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledBreadcrumbs = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<BreadcrumbsProps>((props) => generateStyles(props));
